// No carrier held the text earlier. Where the element's own carrier is older than the
// birth, it was added to a file that already existed and the birth reads as one; where the
// carrier begins here, or where something listed the element before it, the drafted birth
// is an assumption and is named as one rather than read as a derivation.
if (!at || !at.files) {
  if (at?.listedAt || !at?.carrierOlder) el.unfollowed = { listedAt: at?.listedAt ?? null };
  return el;
}

