function carrierIndex(root, paths) {
  const revs = [];
  const wanted = new Set();
  for (const rec of git(root, 'log', '--reverse', '--format=%x01%H %as', '--raw', '--no-abbrev', '--no-renames', '--', ...paths).split('\x01')) {
    const lines = rec.split('\n');
    const [sha, date] = lines[0].split(' ');
    if (!sha) continue;
    const files = [];
    for (const line of lines.slice(1)) {
      const m = /^:\d+ \d+ [0-9a-f]+ ([0-9a-f]+) \w+\t(.+)$/.exec(line);
      if (!m || /^0+$/.test(m[1]) || !couldCarry(m[2])) continue;
      files.push([m[2], m[1]]);
      wanted.add(m[1]);
    }
    if (files.length) revs.push({ sha, date, files });
  }
  const texts = readBlobs(root, [...wanted]);
  const carried = new Map();
  const listed = new Map();
  for (const [sha, text] of texts) { carried.set(sha, searchable(withoutRows(text))); listed.set(sha, searchable(text)); }
  return { revs, carried, listed };
}

